#!/usr/bin/env bash
#
# AI-Generated Code Evaluation
# Generated by: Gemini
# Modified by: Henry Alvarez
# Citations:
#   - journalctl and ss commands: CIS 245 Week 8 Lecture
#   - awk -F: command structure: CIS 245 Awk Lab
#   - Bash scripting syntax: CIS 117 Intro to Linux
#   - tee command for output redirection: https://linuxize.com/post/linux-tee-command/


# ==============================================================================
# Script Name: security_audit.sh
# Description: Cross-distribution security audit script for CentOS Stream 10 
#              and Ubuntu 26.04. 
# Requirements Met:
#   1. Cross-distribution compatibility (systemd-based logs, ss, standard POSIX tools)
#   2. Reports failed SSH logins from the last 24 hours
#   3. Lists UID 0 accounts and accounts with empty passwords
#   4. Lists listening ports using ss
#   5. Saves timestamped output to /var/log/security_audit/
#   6. Fully compatible with cron execution (explicit PATH, non-interactive)
#   7. Read-only (makes no changes or installations)
#   8. Exits with a non-zero code if security findings are present
# ==============================================================================

# Ensure secure execution environment for cron and interactive shells
export PATH="/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin"

# Configuration
AUDIT_DIR="/var/log/security_audit"
TIMESTAMP=$(date +%Y%m%d_%H%M%S)
LOG_FILE="$AUDIT_DIR/audit_${TIMESTAMP}.log"

# Ensure script is run as root (required for /etc/shadow and journalctl access)
if [ "$EUID" -ne 0 ]; then
    echo "[-] Error: This script must be run as root." >&2
    exit 2
fi

# Create audit log directory if it doesn't exist
mkdir -p "$AUDIT_DIR"

# Initialize findings counter (used for exit code)
FINDINGS=0

# Redirect all output and errors to both the log file and stdout
exec > >(tee -a "$LOG_FILE") 2>&1

echo "======================================================================"
echo " Starting Security Audit: $(date)"
echo " Hostname: $(hostname)"
echo " Operating System:"
cat /etc/os-release | grep -E "^(NAME|VERSION)="
echo "======================================================================"
echo ""

# ------------------------------------------------------------------------------
# Section 1: Failed SSH Logins (Last 24 Hours)
# ------------------------------------------------------------------------------
echo "[-] Checking failed SSH logins from the last 24 hours..."
# Supports both 'ssh' (Ubuntu) and 'sshd' (CentOS Stream) service identifiers
FAILED_SSH=$(journalctl -u ssh -u sshd --since "24 hours ago" --no-pager 2>/dev/null | grep -iE "failed|invalid|error" || true)

if [ -n "$FAILED_SSH" ]; then
    echo "[!] WARNING: Failed SSH login attempts detected:"
    echo "$FAILED_SSH"
    # Count failed login occurrences
    FAILED_COUNT=$(echo "$FAILED_SSH" | wc -l)
    FINDINGS=$((FINDINGS + FAILED_COUNT))
else
    echo "[+] No failed SSH logins found in the last 24 hours."
fi
echo ""

# ------------------------------------------------------------------------------
# Section 2: Accounts with Root Privileges (UID 0)
# ------------------------------------------------------------------------------
echo "[-] Checking accounts with root privileges (UID 0)..."
# Extract all accounts with UID 0 from /etc/passwd
UID0_ACCOUNTS=$(awk -F: '($3 == 0) {print $1}' /etc/passwd)
echo "Accounts with UID 0:"
echo "$UID0_ACCOUNTS"

# Check if non-standard UID 0 accounts exist (standard is usually just 'root')
NON_ROOT_UID0=$(echo "$UID0_ACCOUNTS" | grep -v "^root$")
if [ -n "$NON_ROOT_UID0" ]; then
    echo "[!] WARNING: Non-standard UID 0 account(s) detected: $NON_ROOT_UID0"
    FINDINGS=$((FINDINGS + 1))
else
    echo "[+] Only standard 'root' account has UID 0."
fi
echo ""

# ------------------------------------------------------------------------------
# Section 3: Accounts with Empty Passwords
# ------------------------------------------------------------------------------
echo "[-] Checking for accounts with empty passwords..."
# In /etc/shadow, the second field is the password hash. An empty field means no password.
EMPTY_PASS_ACCOUNTS=$(awk -F: '($2 == "") {print $1}' /etc/shadow 2>/dev/null || true)

if [ -n "$EMPTY_PASS_ACCOUNTS" ]; then
    echo "[!] CRITICAL: Accounts with empty passwords found:"
    echo "$EMPTY_PASS_ACCOUNTS"
    FINDINGS=$((FINDINGS + 1))
else
    echo "[+] No accounts with empty passwords detected."
fi
echo ""

# ------------------------------------------------------------------------------
# Section 4: Listening Network Ports
# ------------------------------------------------------------------------------
echo "[-] Listing current listening ports using ss..."
# -t: TCP, -u: UDP, -l: Listening, -n: Numeric addresses, -p: Show process
ss -tulpn
echo ""

# ------------------------------------------------------------------------------
# Audit Summary & Exit Code
# ------------------------------------------------------------------------------
echo "======================================================================"
echo " Audit Completed: $(date)"
echo " Results saved to: $LOG_FILE"
echo " Total Findings / Warnings Count: $FINDINGS"
echo "======================================================================"

if [ "$FINDINGS" -gt 0 ]; then
    echo "[!] Audit finished with findings. Exiting with status 1."
    exit 1
else
    echo "[+] Audit passed successfully with zero findings. Exiting with status 0."
    exit 0
fi
